
'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { supabase } from '@/lib/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { ArrowLeft, Edit, File as FileIcon, Loader2, Save, Trash2, X, Download } from 'lucide-react';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { updateApplicationData, updateApplicationStatus } from '@/app/actions/adminActions';
import type { ApplicationStatus } from '../applications/page';


// This type can be shared across admin pages
export interface StoredApplication {
  id: string;
  type: string;
  applicant_name: string;
  status: string;
  created_at: string;
  data: Record<string, any>;
  user_id?: string;
  rejection_reason?: string;
}

const statusOptions: ApplicationStatus[] = ['Pending', 'Approved', 'Rejected'];

export default function ApplicationDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { toast } = useToast();
  const appId = params.id as string;

  const [application, setApplication] = useState<StoredApplication | null>(null);
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [editedData, setEditedData] = useState<Record<string, any>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isStatusUpdating, setIsStatusUpdating] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  
  const [rejectionReason, setRejectionReason] = useState('');
  const [isRejectionDialogOpen, setIsRejectionDialogOpen] = useState(false);


  const fetchApplication = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('*')
        .eq('id', appId)
        .single();
      
      if (error) throw error;

      setApplication(data as StoredApplication);
      setEditedData(data.data || {});
      setRejectionReason(data.rejection_reason || '');

    } catch (error) {
      console.error("Failed to fetch application:", error);
      toast({ title: "Error", description: "Could not load application details.", variant: "destructive" });
      router.back();
    } finally {
      setLoading(false);
    }
  }, [appId, toast, router]);

  useEffect(() => {
    if (appId) {
      fetchApplication();
    }
  }, [appId, fetchApplication]);

  const handleEditToggle = () => {
    if (isEditing) {
      // If canceling edit, revert changes
      setEditedData(application?.data || {});
    }
    setIsEditing(!isEditing);
  };

  const handleInputChange = (key: string, value: string | boolean) => {
    setEditedData(prev => ({ ...prev, [key]: value }));
  };

  const handleSaveChanges = async () => {
    if (!application) return;
    setIsSaving(true);
    try {
      const result = await updateApplicationData(application.id, editedData);
      if (result.success) {
        toast({ title: "Success", description: "Application data updated successfully." });
        setIsEditing(false);
        fetchApplication(); // Re-fetch to show updated data
      } else {
        throw new Error(result.error);
      }
    } catch (error) {
      console.error("Failed to save changes:", error);
      toast({ title: "Error", description: `Could not save changes: ${error instanceof Error ? error.message : ''}`, variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const handleStatusChange = async (newStatus: ApplicationStatus) => {
      if (!application) return;
      
      if (newStatus === 'Rejected') {
          setIsRejectionDialogOpen(true);
          return;
      }
      
      setIsStatusUpdating(true);
      try {
        const result = await updateApplicationStatus(application.id, newStatus, null); // Clear reason if not rejecting
        if (result.success) {
            toast({ title: "Status Updated", description: `Application has been marked as ${newStatus}.` });
            fetchApplication();
        } else {
            throw new Error(result.error);
        }
      } catch (error) {
          toast({ title: "Error", description: `Could not update status: ${error instanceof Error ? error.message : ''}`, variant: "destructive" });
      } finally {
          setIsStatusUpdating(false);
      }
  };

  const handleRejectionSubmit = async () => {
      if (!application || !rejectionReason.trim()) {
          toast({ title: "Error", description: "Rejection reason cannot be empty.", variant: "destructive" });
          return;
      }
      setIsStatusUpdating(true);
      setIsRejectionDialogOpen(false);
      try {
        const result = await updateApplicationStatus(application.id, 'Rejected', rejectionReason);
        if (result.success) {
            toast({ title: "Application Rejected", description: "The application has been marked as rejected." });
            fetchApplication();
        } else {
            throw new Error(result.error);
        }
      } catch (error) {
           toast({ title: "Error", description: `Could not reject application: ${error instanceof Error ? error.message : ''}`, variant: "destructive" });
      } finally {
          setIsStatusUpdating(false);
      }
  }


  const handleDeleteApplication = async () => {
      if (!application) return;
      // Actual delete logic
      setIsDeleteDialogOpen(false);
      toast({ title: "Action Disabled", description: "Deleting from the detail page is disabled for safety.", variant: "destructive" });
  };
  
  if (loading) {
    return <div className="flex justify-center items-center h-64"><Loader2 className="h-8 w-8 animate-spin" /></div>;
  }

  if (!application) {
    return <div className="text-center text-muted-foreground">Application not found.</div>;
  }

 const renderFieldValue = (key: string, value: any) => {
    // Standardize 'on' to true
    if (value === 'on') value = true;

    if (isEditing) {
      if (typeof value === 'boolean') {
        return (
          <Input 
            type="checkbox" 
            className="w-6 h-6"
            checked={!!editedData[key]} // Coerce to boolean
            onCheckedChange={(checked) => handleInputChange(key, !!checked)}
          />
        );
      }
       if (key.toLowerCase().includes('date') && (typeof value === 'string' && !isNaN(Date.parse(value)))) {
           return (
               <Input 
                  type="text" 
                  value={editedData[key] ? new Date(editedData[key]).toLocaleDateString() : ''} 
                  disabled 
                  className="bg-muted"
                />
           );
       }
       if (typeof value === 'object' && value !== null) {
           // For file objects or nested objects, just show a label in edit mode, as direct editing is complex
           return <p className="text-sm text-muted-foreground">[Complex object - not editable]</p>;
       }
      return <Input value={editedData[key] || ''} onChange={(e) => handleInputChange(key, e.target.value)} />;
    }
    
    // --- Display Mode ---

    if (typeof value === 'boolean') {
      return value ? <Badge>Yes</Badge> : <Badge variant="secondary">No</Badge>;
    }
    if (typeof value === 'object' && value !== null && value.url) {
      return (
        <a href={value.url} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline flex items-center gap-2">
            <Download className="h-4 w-4" /> {value.name || 'Download File'}
        </a>
      );
    }
    if (typeof value === 'object' && value !== null) {
        // This is the new recursive part for nested objects
        const entries = Object.entries(value);
        const hasContent = entries.some(([_, v]) => v);
        
        if (!hasContent) {
             return <p className="text-sm text-muted-foreground italic">None</p>;
        }

        return (
          <div className="flex flex-col gap-2 border-l-2 pl-3 border-muted">
             {entries.map(([nestedKey, nestedValue]) => {
                // Skip if the nested value is falsy (false, null, undefined, '')
                if (!nestedValue) return null;
                
                return (
                     <div key={nestedKey} className="text-xs">
                        <span className="capitalize font-medium text-muted-foreground">
                            {nestedKey.replace(/([A-Z])/g, ' $1').trim()}:
                        </span>
                        <div className="pl-2">
                            {renderFieldValue(nestedKey, nestedValue)}
                        </div>
                    </div>
                );
            })}
          </div>
        );
    }

    if (key.toLowerCase().includes('date') && (typeof value === 'string' && !isNaN(Date.parse(value)))) {
        return <p className="text-sm text-foreground">{new Date(value).toLocaleDateString()}</p>;
    }

    return <p className="text-sm text-foreground">{value || <span className="text-muted-foreground italic">Not provided</span>}</p>;
  };


  return (
    <div className="space-y-6">
      <Button variant="outline" onClick={() => router.back()} className="gap-2">
        <ArrowLeft className="h-4 w-4" /> Back to List
      </Button>
      
      <Card>
        <CardHeader>
          <div className="flex justify-between items-start">
            <div>
              <CardTitle>{application.type}</CardTitle>
              <CardDescription>ID: {application.data.applicationId || application.id}</CardDescription>
            </div>
             <Badge variant={
                application.status === 'Approved' ? 'default' :
                application.status === 'Rejected' ? 'destructive' :
                'secondary'
             } className="capitalize">{application.status}</Badge>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-4">
            <h3 className="text-lg font-semibold text-primary">Applicant Information</h3>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1"><Label>Applicant Name</Label><p className="text-sm">{application.applicant_name}</p></div>
                <div className="space-y-1"><Label>Applicant User ID</Label><p className="text-sm font-mono">{application.user_id}</p></div>
            </div>
          </div>
          <div className="space-y-4">
            <h3 className="text-lg font-semibold text-primary">Application Data</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4">
              {Object.entries(application.data).map(([key, value]) => (
                <div key={key} className="space-y-1">
                  <Label className="capitalize">{key.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ')}</Label>
                  {renderFieldValue(key, value)}
                </div>
              ))}
            </div>
          </div>
           {application.status === 'Rejected' && application.rejection_reason && (
                <div className="p-3 mt-4 rounded-md bg-destructive/10">
                    <h4 className="font-semibold text-destructive text-sm">Reason for Rejection</h4>
                    {isEditing ? (
                         <Textarea 
                            value={rejectionReason} 
                            onChange={(e) => setRejectionReason(e.target.value)} 
                            className="mt-1"
                         />
                    ) : (
                        <p className="text-xs text-destructive/90 mt-1">{application.rejection_reason}</p>
                    )}
                </div>
            )}

        </CardContent>
         <CardFooter className="flex flex-col sm:flex-row justify-between items-center gap-4 border-t pt-6">
            {isEditing ? (
              <div className="flex gap-2">
                <Button onClick={handleSaveChanges} disabled={isSaving}>
                  {isSaving ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Saving...</> : <><Save className="mr-2 h-4 w-4" />Save Changes</>}
                </Button>
                <Button variant="ghost" onClick={handleEditToggle}><X className="mr-2 h-4 w-4" />Cancel</Button>
              </div>
            ) : (
              <Button onClick={handleEditToggle} variant="outline" className="gap-2">
                <Edit className="h-4 w-4" /> Edit Application
              </Button>
            )}
             <div className="flex gap-2 flex-wrap justify-end">
                {statusOptions.map(status => (
                    <Button key={status} size="sm" onClick={() => handleStatusChange(status)} disabled={isStatusUpdating || application.status === status}>
                        {isStatusUpdating ? 'Updating...' : `Mark as ${status}`}
                    </Button>
                ))}
                <Button size="sm" variant="destructive" onClick={() => setIsDeleteDialogOpen(true)} className="gap-2">
                    <Trash2 className="h-4 w-4" /> Delete
                </Button>
            </div>
         </CardFooter>
      </Card>
      
       <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. This will permanently delete this application.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteApplication} className="bg-destructive hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

       <AlertDialog open={isRejectionDialogOpen} onOpenChange={setIsRejectionDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Reason for Rejection</AlertDialogTitle>
            <AlertDialogDescription>
              Please provide a clear reason why this application is being rejected. This will be shown to the user.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="py-4">
             <Textarea 
                placeholder="e.g., Incomplete documentation, incorrect plot information..."
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleRejectionSubmit} disabled={!rejectionReason.trim()}>Submit Rejection</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
